class TestSessionDecoding:
    def test_invalid_session_data_crash_reproduction(self):
        """Test that invalid session data causes crash (should fail before fix)"""
        class FailingSessionStore(SessionBase):
            def __init__(self, session_data):
                self.session_key = 'test_key'
                self._session_cache = None
                self.session_data = session_data

            def load(self):
                return self.decode(self.session_data)

        # This data has incorrect Base64 padding
