            def __init__(self, session_data):
                self.session_key = 'test_key'
                self._session_cache = None
                self.session_data = session_data

            def load(self):
                return self.decode(self.session_data)

        result = EmptySessionStore("").load()
        assert result == {}

    def test_none_session_data(self):
        """Test that None session data returns empty dict"""
        class NoneSessionStore(SessionBase):
            def __init__(self, session_data):
                self.session_key = 'test_key'
                self._session_cache = None
                self.session_data = session_data

            def load(self):
                return self.decode(self.session_data)

        result = NoneSessionStore(None).load()
        assert result == {}

    def test_invalid_signature(self):
        """Test that invalid signature returns empty dict"""
        class InvalidSignatureStore(SessionBase):
            def __init__(self, session_data):
                self.session_key = 'test_key'
                self._session_cache = None
                self.session_data = session_data

            def load(self):
                return self.decode(self.session_data)

        # Create valid session data with wrong signature
        valid_data = signing.dumps({'test': 'data'}, salt='test_salt')
        # Modify the signature part
        modified_data = valid_data[:-10] + 'invalid_sig'

        result = InvalidSignatureStore(modified_data).load()
        assert result == {}

    def test_very_long_session_data(self):
        """Test that very long session data doesn't cause overflow"""
        class LongSessionStore(SessionBase):
            def __init__(self, session_data):
                self.session_key = 'test_key'
                self._session_cache = None
                self.session_data = session_data

            def load(self):
                return self.decode(self.session_data)

        # Create very long session data
        long_data = base64.b64encode(b'a' * 1000000).decode('ascii')

        result = LongSessionStore(long_data).load()
        assert isinstance(result, dict)

